-- =====================================================================
-- 01_schema_and_data.sql
-- Script UNICO de: (A) creacion de la base y el esquema, (B) creacion
-- de las 4 tablas normalizadas, (C) carga del dataset crudo (con nulos
-- intencionales para poder demostrar la limpieza), y (D) limpieza de
-- esos nulos con COALESCE + verificacion de tipos DATE/NUMERIC.
--
-- Requiere psql (usa el meta-comando \c para crear la base y
-- reconectarse a ella dentro del mismo archivo).
--
-- Ejecutar con:
--   psql -U postgres -f 01_schema_and_data.sql
-- =====================================================================

-- =====================================================================
-- PARTE A: Base de datos
-- CREATE DATABASE no puede correr dentro de una transaccion, por eso va
-- suelta, antes de cualquier BEGIN. \c reconecta psql a la base nueva
-- para que el resto del script corra ya "adentro" de capstone_project.
-- =====================================================================
DROP DATABASE IF EXISTS capstone_project;
CREATE DATABASE capstone_project;

\c capstone_project

-- =====================================================================
-- PARTE B: Esquema + tablas + carga de datos (INSERT)
-- Las 4 tablas (categoria, clientes, productos, pedidos) se crean
-- dentro del esquema "project". pedidos se carga con nulos
-- intencionales en order_date/total_amount/shipping_cost -- se
-- resuelven en la PARTE D de este mismo archivo.
-- =====================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS project;

-- Todas las sentencias sin prefijo de esquema que siguen (CREATE TABLE,
-- INSERT, etc.) van a resolver contra "project" gracias a este search_path.
SET search_path TO project;

DROP TABLE IF EXISTS pedidos CASCADE;
DROP TABLE IF EXISTS productos CASCADE;
DROP TABLE IF EXISTS clientes CASCADE;
DROP TABLE IF EXISTS categoria CASCADE;

-- Tabla: project.categoria
CREATE TABLE categoria (
    categoria_id  SERIAL PRIMARY KEY,
    nombre        VARCHAR(100) NOT NULL UNIQUE
);

-- Tabla: project.clientes
CREATE TABLE clientes (
    customer_id       VARCHAR(20) PRIMARY KEY,
    customer_name     VARCHAR(150) NOT NULL,
    customer_email    VARCHAR(150) NOT NULL UNIQUE,
    customer_city     VARCHAR(100),
    customer_country  VARCHAR(100)
);

-- Tabla: project.productos
CREATE TABLE productos (
    product_id    VARCHAR(20) PRIMARY KEY,
    product_name  VARCHAR(150) NOT NULL,
    categoria_id  INT NOT NULL REFERENCES categoria(categoria_id),
    unit_price    NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0)
);

-- Tabla: pedidos
-- NOTA: order_date, total_amount y shipping_cost se dejan SIN 'NOT NULL'
-- a proposito en esta carga inicial, porque el dataset de origen trae
-- nulos reales en esas columnas. El script 02_cleaning.sql los detecta,
-- los resuelve con COALESCE y recien despues endurece el esquema con
-- 'ALTER COLUMN ... SET NOT NULL'.
-- Tabla: project.pedidos
CREATE TABLE pedidos (
    order_id        VARCHAR(20) PRIMARY KEY,
    order_date      DATE,
    customer_id     VARCHAR(20) NOT NULL REFERENCES clientes(customer_id),
    product_id      VARCHAR(20) NOT NULL REFERENCES productos(product_id),
    quantity        INT NOT NULL CHECK (quantity > 0),
    total_amount    NUMERIC(14,2) CHECK (total_amount >= 0),
    shipping_cost   NUMERIC(12,2) CHECK (shipping_cost >= 0),
    payment_method  VARCHAR(50) NOT NULL,
    order_status    VARCHAR(30) NOT NULL
);

-- Indices auxiliares
CREATE INDEX idx_pedidos_customer_id ON pedidos(customer_id);
CREATE INDEX idx_pedidos_product_id ON pedidos(product_id);
CREATE INDEX idx_productos_categoria_id ON productos(categoria_id);
CREATE INDEX idx_pedidos_order_date ON pedidos(order_date);

-- Carga: categoria (7 filas)

SELECT setval(pg_get_serial_sequence('categoria', 'categoria_id'), 7, true);

-- Carga: clientes (350 filas)

-- Carga: productos (70 filas)

-- Carga: pedidos (2000 filas, incluye nulos intencionales
-- en order_date / total_amount / shipping_cost para el paso de limpieza)




COMMIT;

-- =====================================================================
-- PARTE C: Limpieza de datos
--   1) Identificar nulos en columnas criticas (precios, fechas)
--   2) Verificar que los tipos de datos sean correctos (DATE, NUMERIC)
--   3) Resolver los nulos con COALESCE
-- =====================================================================

-- ---------------------------------------------------------------------
-- 2.a) IDENTIFICAR NULOS en columnas criticas (precios y fechas)
-- ---------------------------------------------------------------------
SELECT
    COUNT(*) AS total_pedidos,
    COUNT(*) FILTER (WHERE order_date     IS NULL) AS nulos_order_date,
    COUNT(*) FILTER (WHERE total_amount   IS NULL) AS nulos_total_amount,
    COUNT(*) FILTER (WHERE shipping_cost  IS NULL) AS nulos_shipping_cost
FROM pedidos;

-- Detalle de ejemplo de filas afectadas (antes de limpiar)
SELECT order_id, order_date, total_amount, shipping_cost
FROM pedidos
WHERE order_date IS NULL OR total_amount IS NULL OR shipping_cost IS NULL
ORDER BY order_id
LIMIT 10;

-- ---------------------------------------------------------------------
-- 2.b) VERIFICAR TIPOS DE DATOS antes de limpiar (deben ser DATE / NUMERIC)
-- ---------------------------------------------------------------------
SELECT table_schema, table_name, column_name, data_type, numeric_precision, numeric_scale
FROM information_schema.columns
WHERE table_schema = 'project'
  AND table_name = 'pedidos'
  AND column_name IN ('order_date', 'total_amount', 'shipping_cost')
ORDER BY column_name;
-- order_date     -> data_type debe ser 'date'
-- total_amount   -> data_type debe ser 'numeric'
-- shipping_cost  -> data_type debe ser 'numeric'
-- (Si algo viniera como TEXT, aca se detectaria para corregir con
--  ALTER TABLE ... ALTER COLUMN ... TYPE DATE/NUMERIC USING ...)

-- ---------------------------------------------------------------------
-- 2.c) GESTIONAR NULOS CON COALESCE
-- ---------------------------------------------------------------------

-- shipping_cost: si no se registro el costo de envio, se asume envio
-- gratis (0), que es la politica mas comun para pedidos sin dato.
UPDATE pedidos
SET shipping_cost = COALESCE(shipping_cost, 0)
WHERE shipping_cost IS NULL;

-- total_amount: si falta el monto del pedido, se recalcula a partir del
-- precio unitario del producto (tabla productos) y la cantidad pedida,
-- en vez de imputar un valor arbitrario.
UPDATE pedidos p
SET total_amount = COALESCE(p.total_amount, ROUND(pr.unit_price * p.quantity, 2))
FROM productos pr
WHERE p.product_id = pr.product_id
  AND p.total_amount IS NULL;

-- order_date: si falta la fecha del pedido, se imputa con la fecha mas
-- frecuente del dataset (moda). Es una simplificacion razonable para
-- este ejercicio; en un caso real se buscaria el dato en el sistema de
-- origen o se marcaria el registro para revision manual.
UPDATE pedidos
SET order_date = COALESCE(
    order_date,
    (SELECT order_date
     FROM pedidos
     WHERE order_date IS NOT NULL
     GROUP BY order_date
     ORDER BY COUNT(*) DESC, order_date
     LIMIT 1)
)
WHERE order_date IS NULL;

-- ---------------------------------------------------------------------
-- Verificacion POST-limpieza: ya no deberia haber nulos
-- ---------------------------------------------------------------------
SELECT
    COUNT(*) AS total_pedidos,
    COUNT(*) FILTER (WHERE order_date     IS NULL) AS nulos_order_date,
    COUNT(*) FILTER (WHERE total_amount   IS NULL) AS nulos_total_amount,
    COUNT(*) FILTER (WHERE shipping_cost  IS NULL) AS nulos_shipping_cost
FROM pedidos;

-- ---------------------------------------------------------------------
-- Endurecer el esquema: ahora que los datos estan limpios, se refuerza
-- la integridad exigiendo NOT NULL (evita que vuelvan a colarse nulos)
-- ---------------------------------------------------------------------
ALTER TABLE pedidos ALTER COLUMN order_date     SET NOT NULL;
ALTER TABLE pedidos ALTER COLUMN total_amount   SET NOT NULL;
ALTER TABLE pedidos ALTER COLUMN shipping_cost  SET NOT NULL;

-- Verificacion final de tipos (deben seguir siendo DATE / NUMERIC, y
-- ahora tambien 'is_nullable' = 'NO')
SELECT table_schema, table_name, column_name, data_type, is_nullable
FROM information_schema.columns
WHERE table_schema = 'project'
  AND table_name = 'pedidos'
  AND column_name IN ('order_date', 'total_amount', 'shipping_cost')
ORDER BY column_name;
